func (s *Service) AllTasks(ctx context.Context, serviceName string, params ...ListTasksParams) iter.Seq2[*DedicatedNasTaskTask, error] {
	return ovh.Each(ctx,
		func(ctx context.Context) ([]int, error) {
			return s.ListTasks(ctx, serviceName, params...)
		},
		func(ctx context.Context, listedID int) (*DedicatedNasTaskTask, error) {
			return s.GetTask(ctx, serviceName, listedID)
		})
}

